llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In humans, phytoene, a C40 isoprenoid hydrocarbon, showed an estimated absolute bioavailability of 58.5 ± 18.9%, which superficially supports high absorption for long isoprenoid lipids; however, phytoene is much smaller (MW ~544) and lacks the polar quinone head of the query, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "In humans, lycopene, a long-chain isoprenoid carotenoid, showed only ~2.6% systemic availability from a 38-mg capsule dose, demonstrating that extreme lipophilicity and large molecular size can result in very low oral bioavailability; this transfers to the query's similar physicochemical liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A tocotrienol-rich fraction, combining a polar chromanol head with an isoprenoid tail, was reported to have poor oral bioavailability in humans; this is a closer structural analogy to the quinone-headed polyprenyl query and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a prenylated polyphenol with multiple isoprene units, showed high oral bioavailability in volunteers, but its lower structural similarity and different core chemistry reduce the weight of this supportive evidence for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a very large, highly lipophilic polyprenyl quinone (CoQ10-like). Although the closest analogue phytoene shows high absorption in humans, its smaller hydrocarbon structure limits transfer. More relevant analogues with polar heads and long isoprenoid tails (tocotrienol) and carotenoids (lycopene) show low or poor oral bioavailability, consistent with the physicochemical liabilities of high MW, extreme logP, and poor solubility. Therefore F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for CoQ10 itself is available in the evidence set.",
    "The phytoene high-bioavailability result comes from a single compartmental-model study and may not reflect true absolute F.",
    "Formulation effects, which can substantially alter absorption of highly lipophilic molecules, are not captured in the query assessment."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

